/*
 * View one order.
 * Validates the order code and opens the page generated by showOrder.php (GET).
 */

const ORDER_CODE_PATTERN = /^[A-Za-z0-9-]{3,20}$/;

// Shows an error about the order code and marks the field
function showCodeError(field, text) {
    showMessage("search-message", text, "error");
    field.classList.add("invalid");
    field.focus();
}

function handleSearchSubmit(event) {
    event.preventDefault();
    const field = document.getElementById("code");
    const code = field.value.trim();

    if (code === "") {
        showCodeError(field, "Please enter the order code.");
    } else if (!ORDER_CODE_PATTERN.test(code)) {
        showCodeError(field, "The order code must have 3 to 20 letters, numbers or hyphens.");
    } else {
        goTo(SERVER_URL + "showOrder.php?code=" + encodeURIComponent(code));
    }
}

requireSession();
document.getElementById("search-form").addEventListener("submit", handleSearchSubmit);
